using DistributedMonolith.Products.Api;using DistributedMonolith.Products.Application;using DistributedMonolith.Products.Infrastructure;using Microsoft.EntityFrameworkCore;
var builder=WebApplication.CreateBuilder(args);builder.Services.AddDbContext<ProductsDbContext>(o=>o.UseSqlite(builder.Configuration.GetConnectionString("Database")??"Data Source=Products.db"));builder.Services.AddScoped<ProductService>();builder.Services.AddEndpointsApiExplorer();builder.Services.AddSwaggerGen();var app=builder.Build();using(var s=app.Services.CreateScope()){s.ServiceProvider.GetRequiredService<ProductsDbContext>().Database.EnsureCreated();}app.UseSwagger();app.UseSwaggerUI();app.MapProductEndpoints();app.MapGet("/health",()=>Results.Ok());app.Run();
